-- Função para verificar se o jogo atual é suportado
local function isGameSupported()
    local currentPlaceId = game.PlaceId
    for _, supportedId in ipairs(SUPPORTED_GAME_IDS) do
        if currentPlaceId == supportedId then
            return true
        end
    end
    return false
end

